            foreach(var value in Get(wall,"openings",new GArray()).AsGodotArray()){var opening=value.AsGodotDictionary();var direction=(last-first).Normalized();var center=first.Lerp(last,(float)Get(opening,"t",.5).AsDouble());float width=(float)Get(opening,"width",1.0).AsDouble();string kind=Get(opening,"type","door").AsString();var accent=new Color(kind=="window"?"76bdff":kind=="arch"?"ffc778":"76ddac");owner.DrawLine(to_screen(owner,center-direction*width*.5f),to_screen(owner,center+direction*width*.5f),new Color("101e29"),Math.Max(5,thickness+3),true);owner.DrawLine(to_screen(owner,center-direction*width*.5f),to_screen(owner,center+direction*width*.5f),accent,2,true);owner.DrawCircle(to_screen(owner,center),4,accent);}
            if(selected){owner.DrawCircle(start,7,new Color("85f2d4"),false,2,true);owner.DrawCircle(end,7,new Color("85f2d4"),false,2,true);owner.DrawString(ThemeDB.FallbackFont,(start+end)*.5f+new Vector2(0,-10),first.DistanceTo(last).ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+" m",HorizontalAlignment.Left,-1,12,color);}
        }
        foreach(var value in source.Get("stairs").AsGodotArray()){var stair=value.AsGodotDictionary();string id=floor["id"].AsString();if(Get(stair,"from", "").AsString()!=id&&Get(stair,"to", "").AsString()!=id)continue;var bounds=_geometry.stair_bounds(stair);var rect=new Rect2(to_screen(owner,bounds.Position),bounds.Size*(float)zoom);owner.DrawRect(rect,new Color(.9f,.67f,.3f,.15f));owner.DrawRect(rect,new Color("e6b864"),false,2);}var drag=owner.Get("_drag").AsGodotDictionary();string tool=Get(drag,"kind", "").AsString();if(drag.Count>0&&tool is "Wall" or "Room"){var start=to_screen(owner,drag["start"].AsVector2());var end=to_screen(owner,drag["point"].AsVector2());if(tool=="Room"){var rect=new Rect2(start,end-start).Abs();owner.DrawRect(rect,new Color(.3f,.9f,.7f,.12f));owner.DrawRect(rect,new Color("8df4d2"),false,2);}else owner.DrawLine(start,end,new Color("8df4d2"),2,true);}
